Section CANSEC1. Context {rc : runConstT}.
Section Z4S1J.
  Variable AI : AMallocIface.
  Notation CI := (aci AI).
  Variables (L : alayout) (RNG : footprint) (st : astate) (LB : list ablock) (rng_fs : alayout -> footprint -> Prop).
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (FR : bvmap 5 word) (fc : bv 32) (m0 : amem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte) (pdt : aptr)
            (SBL SBH : Z) (rstk : region).
  Notation SP := (bv_unsigned sp).
  Notation SPF := (SP + -576).
  Notation n := (zlen src).
  Notation seg := ((dcap + 3) / 4).
  Notation DTL := (DTABLE_BYTES mtl).
  Hypothesis AH : AHEAP AI L RNG st LB m0.
  Hypothesis NFK : forall F k, ~ In (mkABlock (ABFake 0) F k) LB.
  Hypothesis ABL : forall b, In b LB -> ablk (ab_addr b) (ab_addr b + ab_size b).
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl.
  Hypothesis HDT : In (HB pdt DT DTL) LB.
  Hypothesis TOK : x2_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^tl)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 4 * 2^tl.
  Hypothesis DSTF : (DST = 0 /\ dcap = 0) \/ (exists pb, In (HB pb DST dcap) LB).
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis NSM : n < 2^26.
  Hypothesis S16 : 16 <= SS.
  Hypothesis SRCB : 0 < n -> exists p, In (HB p SBL (SBH - SBL)) LB /\ SBL <= SS /\ SS + n <= SBH.
  Hypothesis DJ1 : DT + DTL <= SS \/ SS + n <= DT.
  Hypothesis DJ2 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis DJ3 : DT + DTL <= DST \/ DST + dcap <= DT.
  Hypothesis LOA : ATOP + 4096 <= lo.
  Hypothesis LOS : lo <= SP - HUF_DEC_STACK_A.
  Hypothesis SPT : SP + 16 < al_top L.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis TPA : tp = Z_to_bv 64 ATP.
  Hypothesis HINV : harness_invA m0.
  Hypothesis RCL : rclean m0 rstk.
  Hypothesis RLO : r_lo rstk <= lo.
  Hypothesis RHI : SP <= r_hi rstk.
  Hypothesis RRL : ATOP <= r_rlo rstk.
  Hypothesis RRS : rrng RNG rstk.
  Hypothesis WSK : rng RNG lo (al_top L - lo).
  Hypothesis WIM : rng_aimg RNG.
  Hypothesis WIS : rng_aimg_sh RNG.
  Hypothesis WFS : rng_fs L RNG.

  Notation DW := [(lo, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_postA AI L RNG ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc st LB DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Notation ZB l := (l AI L RNG st LB rng_fs ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0 DST dcap SS DT mtl tl lo src
                      cells cbs pdt SBL SBH rstk AH NFK ABL MTL TLM HDT TOK ECB LCB DSTF DC BYS NSM S16 SRCB DJ1 DJ2 DJ3
                      LOA LOS SPT SP16 TPA HINV RCL RLO RHI RRL RRS WSK WIM WIS WFS) (only parsing).
  Notation Z4SF' mm spl bd4 := (Z4SF ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT mtl tl lo src cbs mm spl bd4)
    (only parsing).

  (* [comment removed for export] *)
  Notation Wtot := [(DST, DST + dcap); (SP + -576 + 272, SP + -576 + 312); (SP + -576 + 320, SP + -576 + 328);
                    (SP + -576 + 336, SP + -576 + 344)].

  Hypothesis S2G : z4s2_goal AI L RNG st LB ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 FR fc m0 DST dcap SS DT mtl tl lo
                      src cbs.

  Section STREAMS.
  Variables (l1 l2 l3 : Z).
  Hypothesis HL1 : 1 <= l1.
  Hypothesis HL2 : 1 <= l2.
  Hypothesis HL3 : 1 <= l3.
  Hypothesis HLN : 6 + l1 + l2 + l3 + 1 <= n.
  Hypothesis D6 : 6 <= dcap.
  Hypothesis SEG3 : 3 * seg <= dcap.
  Notation L4 := (n - (6 + l1 + l2 + l3)).

  Notation SPA1 w40 w272 w280 pt3 c4 c1 j0 j1 :=
    (SPA w40 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + seg)) (Z_to_bv 64 (SS + 6 + l1))
         (Z_to_bv 64 (DST + 3 * seg)) (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 (DST + 2 * seg)) (Z_to_bv 64 (SS + 6 + l1 + l2))
         (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + 8)) (Z_to_bv 64 (DST + dcap - 7)) (Z_to_bv 64 (SS + 6 + 8))
         (Z_to_bv 64 (SS + 6 + l1 + 8)) (Z_to_bv 64 (SS + 6 + l1 + l2 + 8)) w272 w280
         (Z_to_bv 64 (SS + 6 + l1 + l2 + pt3)) c4 c1 (Z_to_bv 64 (DT + 4)) j0 j1) (only parsing).
  Notation BD41 c4 b4o jp pt4 :=
    (BD4A c4 b4o jp (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + pt4)) (Z_to_bv 64 (SS + 6 + l1 + l2 + l3))
          (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + 8))) (only parsing).

  (* [comment removed for export] *)
  Definition Z1HD (mm : amem) (q1 q2 q3 q4 pt1 pt2 pt3 pt4 b1 b2 b3 b4 : Z) (c1 c4 b4o w40 w272 w280 : word)
             (j0 j1 jp : list byte) : Prop :=
    Z4SF' mm (SPA1 w40 w272 w280 pt3 c4 c1 j0 j1) (BD41 c4 b4o jp pt4) /\
    z1hd l1 pt1 b1 /\ z1hd l2 pt2 b2 /\ z1hd l3 pt3 b3 /\ z1hd L4 pt4 b4 /\ z1ops seg q1 q2 q3 q4 /\ q4 + 8 <= dcap.

  (* [comment removed for export] *)
  Notation ZH mm q1 q2 q3 q4 pt1 pt2 pt4 b1 b2 b3 b4 c2 c3 x5 x6 x7 x8 x11 x14 x16 x17 x21 x23 x25 x31 :=
    (MS (mkR (Z_to_bv 64 b2) (Z_to_bv 64 (SP + -576)) gp tp x5 x6 x7 x8 (Z_to_bv 64 b1) (Z_to_bv 64 (DST + q4)) x11
             (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + pt4)) (Z_to_bv 64 (DST + q3)) x14 (Z_to_bv 64 (DST + q2)) x16 x17
             (Z_to_bv 64 b3) c3 (Z_to_bv 64 (DT + 4)) x21 (Z_to_bv 64 (SS + 6 + l1 + pt2)) x23 (Z_to_bv 64 (DST + q1)) x25
             (Z_to_bv 64 (SS + 6 + pt1)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) c2 (Z_to_bv 64 b4) x31)
        FR (Z_to_bv 64 0x88820) fc None mm (seg_rom asegs)) (only parsing).

  Ltac ztoF pc := repeat (lazymatch goal with |- evtF _ _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

  (* [comment removed for export] *)
  Lemma z4s1_j4 : forall mm (q1 q2 q3 q4 pt1 pt2 pt3 pt4 Q1 Q2 Q3 Q4 ST1 ST2 ST3 ST4 : Z)
                         (e13 e14 e15 e16 b1w b2w b3w b4w c1 c2 c3 c4 b4o w40 : word) (j0 j1 jp : list byte)
                         (j5 j9 j16 j20 j23 j24 j29 : word),
    Z4SF' mm (SPA1 w40 e14 e13 pt3 c4 c1 j0 j1) (BD41 c4 b4o jp pt4) ->
    z1ops seg q1 q2 q3 q4 -> q4 + 8 <= dcap ->
    DST + q1 + 4 <= Q1 + bv_unsigned e13 <= DST + q1 + 8 -> DST + q2 + 4 <= Q2 + bv_unsigned e14 <= DST + q2 + 8 ->
    DST + q3 + 4 <= Q3 + bv_unsigned e15 <= DST + q3 + 8 -> DST + q4 + 4 <= Q4 + bv_unsigned e16 <= DST + q4 + 8 ->
    DST <= Q1 <= DST + dcap -> DST <= Q2 <= DST + dcap -> DST <= Q3 <= DST + dcap -> DST <= Q4 <= DST + dcap ->
    1 <= bv_unsigned e13 <= 2 -> 1 <= bv_unsigned e14 <= 2 -> 1 <= bv_unsigned e15 <= 2 -> 1 <= bv_unsigned e16 <= 2 ->
    z1rel l1 pt1 (bv_unsigned b1w) ST1 -> z1rel l2 pt2 (bv_unsigned b2w) ST2 -> z1rel l3 pt3 (bv_unsigned b3w) ST3 ->
    z1rel L4 pt4 (bv_unsigned b4w) ST4 ->
    (forall mm' (q1' q2' q3' q4' pt1' pt2' pt3' pt4' b1' b2' b3' b4' : Z) (c1' c2' c3' c4' b4o' w40' w272' w280' : word)
            (j0' j1' jp' : list byte) (x5 x6 x7 x8 x11 x14 x16 x17 x21 x23 x25 x31 : word),
       Z1HD mm' q1' q2' q3' q4' pt1' pt2' pt3' pt4' b1' b2' b3' b4' c1' c4' b4o' w40' w272' w280' j0' j1' jp' ->
       q4 + 4 <= q4' ->
       evtF asegs RNG POST (ZH mm' q1' q2' q3' q4' pt1' pt2' pt4' b1' b2' b3' b4' c2' c3' x5 x6 x7 x8 x11 x14 x16 x17 x21 x23
                               x25 x31)) ->
    evtF asegs RNG POST
      (MS (mkR b2w (Z_to_bv 64 (SP + -576)) gp tp j5 (Z_to_bv 64 ST4) (Z_to_bv 64 ST3) c2 j9 (Z_to_bv 64 Q1) e16
               (Z_to_bv 64 (SS + 6 + l1 + l2 + l3 + pt4)) (Z_to_bv 64 Q3) (Z_to_bv 64 Q4) (Z_to_bv 64 Q2) j16
               (Z_to_bv 64 ST1) b3w c3 j20 e15 (Z_to_bv 64 (SS + 6 + l1 + pt2)) j23 j24 (Z_to_bv 64 ST2)
               (Z_to_bv 64 (SS + 6 + pt1)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (64 - tl)) j29 b4w b1w)
          FR (Z_to_bv 64 0x89384) fc None mm (seg_rom asegs)).
